package com.oldschoolnetwork.core.lite;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.text.Html;import com.oldschoolnetwork.lite.*;import org.json.*;
public final class RegistrationActivity extends Activity {
 private static final String VERSION="2026-10-19.1";private final Handler ui=new Handler();private boolean read,loaded;private TextView status;private CheckBox accept;
 public void onCreate(Bundle saved){super.onCreate(saved);setContentView(R.layout.registration);status=(TextView)findViewById(R.id.status);accept=(CheckBox)findViewById(R.id.accept);read=saved!=null&&saved.getBoolean("rules_read");accept.setEnabled(read);
  findViewById(R.id.read_rules).setOnClickListener(new View.OnClickListener(){public void onClick(View v){rules();}});
  findViewById(R.id.rules_back).setOnClickListener(new View.OnClickListener(){public void onClick(View v){((ViewFlipper)findViewById(R.id.pages)).setDisplayedChild(0);}});
  findViewById(R.id.create).setOnClickListener(new View.OnClickListener(){public void onClick(View v){register();}});
  final ScrollView scroll=(ScrollView)findViewById(R.id.rules_scroll);scroll.getViewTreeObserver().addOnScrollChangedListener(new android.view.ViewTreeObserver.OnScrollChangedListener(){public void onScrollChanged(){if(loaded&&scroll.getChildAt(0).getHeight()>0&&scroll.getChildAt(0).getBottom()<=scroll.getHeight()+scroll.getScrollY()+2){read=true;accept.setEnabled(true);}}});
 }
 private String field(int id){return ((EditText)findViewById(id)).getText().toString().trim();}
 private void rules(){loaded=false;((ViewFlipper)findViewById(R.id.pages)).setDisplayedChild(1);((TextView)findViewById(R.id.rules_text)).setText("Loading current Platform Rules…");Api.WORK.execute(new Runnable(){public void run(){try{
  String html=new String(HttpsTransport.request(RegistrationActivity.this,"https://api.oldschoolnetwork.online/v1/on-account/web/terms.html",null,512*1024),"UTF-8");if(!html.contains("var termsVersion='"+VERSION+"'"))throw new Exception("The current Platform Rules are not available yet.");
  final CharSequence text=Html.fromHtml(html.replaceAll("(?is)<script\\b[^>]*>.*?</script>","").replaceAll("(?is)<style\\b[^>]*>.*?</style>",""));ui.post(new Runnable(){public void run(){if(isFinishing())return;loaded=true;((TextView)findViewById(R.id.rules_text)).setText(text);findViewById(R.id.rules_scroll).post(new Runnable(){public void run(){ScrollView scroll=(ScrollView)findViewById(R.id.rules_scroll);if(scroll.getChildAt(0).getHeight()<=scroll.getHeight()){read=true;accept.setEnabled(true);}}});}});
 }catch(final Exception error){ui.post(new Runnable(){public void run(){((TextView)findViewById(R.id.rules_text)).setText("Could not load rules. "+error.getMessage());read=false;accept.setEnabled(false);}});}}});}
 private void register(){if(!read||!accept.isChecked()){status.setText("Read the Platform Rules to the end, then accept them.");return;}final JSONObject body=new JSONObject();try{String email=field(R.id.email),username=field(R.id.username),name=field(R.id.name),password=((EditText)findViewById(R.id.password)).getText().toString();if(!android.util.Patterns.EMAIL_ADDRESS.matcher(email).matches()||!username.matches("[a-zA-Z0-9._]{3,25}")||name.length()==0||password.length()<6){status.setText("Enter a name, valid email, username (3–25 letters, digits, dots or underscores) and a password of at least 6 characters.");return;}body.put("email",email).put("username",username).put("name",name).put("surname",field(R.id.surname)).put("password",password).put("terms_accepted",true).put("terms_version",VERSION);}catch(Exception e){return;}
  findViewById(R.id.create).setEnabled(false);status.setText("Creating your account…");Api.WORK.execute(new Runnable(){public void run(){try{byte[] raw=HttpsTransport.request(RegistrationActivity.this,Api.ENDPOINT.replace("ecosystem.php","register.php"),body.toString().getBytes("UTF-8"),1024*1024);final JSONObject result=new JSONObject(new String(raw,"UTF-8"));ui.post(new Runnable(){public void run(){if(isFinishing())return;findViewById(R.id.create).setEnabled(true);((EditText)findViewById(R.id.password)).setText("");status.setText(result.optString("message"));if("success".equals(result.optString("status")))new AlertDialog.Builder(RegistrationActivity.this).setTitle("Account created").setMessage("You can now sign in to ON Core Lite.").setPositiveButton("Sign in",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){finish();}}).show();}});}catch(final Exception error){ui.post(new Runnable(){public void run(){findViewById(R.id.create).setEnabled(true);status.setText(error.getMessage());}});}}});
 }
 protected void onSaveInstanceState(Bundle b){b.putBoolean("rules_read",read);super.onSaveInstanceState(b);}
}
